import pandas as pd

def calculate_team_standings(team_stats: pd.DataFrame) -> pd.DataFrame:
    if team_stats.empty:
        return pd.DataFrame(columns=['team_id', 'team_name', 'points', 'position'])

    team_stats['points'] = team_stats['wins'] * 3 + team_stats['draws'] * 1
    team_stats['position'] = team_stats['points'].rank(method='min', ascending=False).astype(int)

    result = team_stats[['team_id', 'team_name', 'points', 'position']]
    return result.sort_values(by=['points', 'team_name'], ascending=[False, True])
